'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isAlmostSameValuef = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var isPositiveZerof = require( '@stdlib/math/base/assert/is-positive-zerof' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var MAX_LN = require( '@stdlib/constants/float32/max-ln' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var expf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( expf instanceof Error )
};


// FIXTURES //

var mediumNegative = require( './fixtures/julia/medium_negative.json' );
var mediumPositive = require( './fixtures/julia/medium_positive.json' );
var smallNegative = require( './fixtures/julia/small_negative.json' );
var smallPositive = require( './fixtures/julia/small_positive.json' );
var tiny = require( './fixtures/julia/tiny.json' );


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof expf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function accurately computes the natural exponential function for negative medium numbers', opts, function test( t ) {
	var expected;
	var x;
	var v;
	var e;
	var i;

	x = mediumNegative.x;
	expected = mediumNegative.expected;

	for ( i = 0; i < x.length; i++ ) {
		v = expf( f32( x[ i ] ) );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( v, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes the natural exponential function for positive medium numbers', opts, function test( t ) {
	var expected;
	var x;
	var v;
	var e;
	var i;

	x = mediumPositive.x;
	expected = mediumPositive.expected;

	for ( i = 0; i < x.length; i++ ) {
		v = expf( f32( x[ i ] ) );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( v, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes the natural exponential function for negative small numbers', opts, function test( t ) {
	var expected;
	var x;
	var v;
	var e;
	var i;

	x = smallNegative.x;
	expected = smallNegative.expected;

	for ( i = 0; i < x.length; i++ ) {
		v = expf( f32( x[ i ] ) );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( v, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes the natural exponential function for positive small numbers', opts, function test( t ) {
	var expected;
	var x;
	var v;
	var e;
	var i;

	x = smallPositive.x;
	expected = smallPositive.expected;

	for ( i = 0; i < x.length; i++ ) {
		v = expf( f32( x[ i ] ) );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( v, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes the natural exponential function for very small `x`', opts, function test( t ) {
	var expected;
	var x;
	var v;
	var e;
	var i;

	x = tiny.x;
	expected = tiny.expected;

	for ( i = 0; i < x.length; i++ ) {
		v = expf( f32( x[ i ] ) );
		e = f32( expected[ i ] );
		t.strictEqual( v, e, 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns `+infinity` for very large `x`', opts, function test( t ) {
	var val = expf( MAX_LN );
	t.strictEqual( val, PINF, 'returns expected value' );

	val = expf( f32( 100.0 ) );
	t.strictEqual( val, PINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns a finite value for `x` just below the overflow threshold', opts, function test( t ) {
	var val = expf( f32( 88.72283172607422 ) );
	t.strictEqual( val, f32( 3.402798519021476e+38 ), 'returns expected value' );
	t.end();
});

tape( 'the function returns `0` for very large negative `x`', opts, function test( t ) {
	var val = expf( f32( -103.97208404541016 ) );
	t.strictEqual( isPositiveZerof( val ), true, 'returns expected value' );

	val = expf( f32( -110.0 ) );
	t.strictEqual( isPositiveZerof( val ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `0` if provided a `-infinity`', opts, function test( t ) {
	var val = expf( NINF );
	t.strictEqual( isPositiveZerof( val ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+infinity` if provided a `+infinity`', opts, function test( t ) {
	var val = expf( PINF );
	t.strictEqual( val, PINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `NaN` if provided a `NaN`', opts, function test( t ) {
	var val = expf( NaN );
	t.strictEqual( isnanf( val ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `1` if provided `+-0`', opts, function test( t ) {
	var val;

	val = expf( f32( -0.0 ) );
	t.strictEqual( val, f32( 1.0 ), 'returns expected value' );

	val = expf( f32( +0.0 ) );
	t.strictEqual( val, f32( 1.0 ), 'returns expected value' );

	t.end();
});
